import { test, expect, expectStatus, type Document, type DocumentKind, type Extraction, type Vendor } from "../../fixtures";

test(
  "after a replacement, only the new document waits for review",
  { tag: "@LIF-05" },
  async ({ apiAs, factory }) => {
    // Arrange: a submitted vendor whose insurance and contract were approved and whose w9 was rejected.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
    for (const kind of ["insurance_certificate", "contract"] as const) {
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
        200,
      );
    }
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "Signature missing" },
      }),
      200,
    );

    // Act: upload a new w9, wait for it to be extracted, and submit the vendor again.
    const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
    await expect
      .poll(
        async () =>
          (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
        { message: "replacement w9 finishes extraction", timeout: 30_000 },
      )
      .toBe("extracted");
    const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Assert: the vendor is back in review, and the queue holds exactly one pending extraction, the w9.
    expect(submitted.status).toBe("in_review");
    const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("in_review");

    const queue = await expectStatus<{ vendor_id: string; extractions: (Extraction & { kind: DocumentKind })[] }[]>(
      await reviewer.get("/api/review-queue"),
      200,
    );
    const item = queue.find((entry) => entry.vendor_id === vendor.id);
    expect(item, "the vendor is listed in the review queue").toBeDefined();
    const pending = item?.extractions.filter((extraction) => extraction.status === "pending_review") ?? [];
    expect(pending.map((extraction) => extraction.kind)).toEqual(["w9"]);
  },
);
